style.css:
/* =========================================================
   YOUTUBE — iOS 26 LIQUID GLASS
   LIGHT / WHITE EDITION
   ========================================================= */


/* ---------- GLOBAL BACKGROUND ---------- */

body {
  background: #eef0f3 !important;
  background-image: url("https://i.pinimg.com/736x/d7/2e/eb/d72eeb87a3748e574645e9037d6e33af.jpg") !important;
  background-size: cover !important;
  background-position: center center !important;
  background-attachment: fixed !important;
}

ytd-app {
  background: transparent !important;
}


/* ---------- HOME PAGE ---------- */

ytd-rich-grid-renderer {
  background: transparent !important;
}

ytd-rich-item-renderer {
  background: rgba(255, 255, 255, 0.52) !important;
  border: 1px solid rgba(255, 255, 255, 0.92) !important;
  border-radius: 22px !important;
  box-shadow:
    0 8px 25px rgba(0, 0, 0, 0.10),
    inset 0 1px 2px rgba(255, 255, 255, 0.95) !important;
  overflow: hidden !important;
  transition: all 0.2s ease !important;
}

ytd-rich-item-renderer:hover {
  background: rgba(255, 255, 255, 0.68) !important;
  box-shadow:
    0 12px 30px rgba(0, 0, 0, 0.13),
    inset 0 1px 3px rgba(255, 255, 255, 1) !important;
}


/* ---------- TOP BAR ---------- */

ytd-masthead {
  background: rgba(255, 255, 255, 0.72) !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.92) !important;
  box-shadow:
    0 4px 18px rgba(0, 0, 0, 0.06),
    inset 0 1px 2px rgba(255, 255, 255, 0.9) !important;
}


/* ---------- SEARCH BAR ---------- */

ytd-searchbox {
  background: rgba(255, 255, 255, 0.68) !important;
  border: 1px solid rgba(255, 255, 255, 0.9) !important;
  border-radius: 20px !important;
  box-shadow:
    0 4px 14px rgba(0, 0, 0, 0.06),
    inset 0 1px 2px rgba(255, 255, 255, 0.95) !important;
  overflow: hidden !important;
}

ytd-searchbox:hover {
  background: rgba(255, 255, 255, 0.82) !important;
  box-shadow:
    0 6px 18px rgba(0, 0, 0, 0.09),
    inset 0 1px 3px rgba(255, 255, 255, 1) !important;
}


/* ---------- SIDEBAR ---------- */

ytd-guide-entry-renderer {
  background: rgba(255, 255, 255, 0.55) !important;
  border: 1px solid rgba(255, 255, 255, 0.45) !important;
  border-radius: 16px !important;
  margin: 3px 8px !important;
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.04) !important;
}

ytd-guide-entry-renderer:hover {
  background: rgba(255, 255, 255, 0.86) !important;
  box-shadow: 0 5px 14px rgba(0, 0, 0, 0.07) !important;
}

ytd-mini-guide-entry-renderer {
  border-radius: 14px !important;
}

ytd-mini-guide-entry-renderer:hover {
  background: rgba(255, 255, 255, 0.75) !important;
}


/* ---------- CATEGORY CHIPS ---------- */

yt-chip-cloud-chip-renderer {
  background: rgba(255, 255, 255, 0.62) !important;
  border: 1px solid rgba(255, 255, 255, 0.88) !important;
  border-radius: 18px !important;
  box-shadow:
    0 3px 10px rgba(0, 0, 0, 0.05),
    inset 0 1px 1px rgba(255, 255, 255, 0.9) !important;
}

yt-chip-cloud-chip-renderer:hover {
  background: rgba(255, 255, 255, 0.92) !important;
  box-shadow:
    0 5px 14px rgba(0, 0, 0, 0.08),
    inset 0 1px 2px rgba(255, 255, 255, 1) !important;
}


/* ---------- GENERAL BUTTONS ---------- */

ytd-button-renderer {
  border-radius: 16px !important;
}

ytd-button-renderer yt-button-shape button {
  background: rgba(255, 255, 255, 0.65) !important;
  border: 1px solid rgba(255, 255, 255, 0.88) !important;
  border-radius: 16px !important;
  box-shadow:
    0 3px 10px rgba(0, 0, 0, 0.05),
    inset 0 1px 1px rgba(255, 255, 255, 0.9) !important;
}

ytd-button-renderer yt-button-shape button:hover {
  background: rgba(255, 255, 255, 0.94) !important;
  box-shadow:
    0 5px 15px rgba(0, 0, 0, 0.09),
    inset 0 1px 2px rgba(255, 255, 255, 1) !important;
}


/* ---------- ICON BUTTONS ---------- */

ytd-menu-renderer {
  background: rgba(255, 255, 255, 0.62) !important;
  border: 1px solid rgba(255, 255, 255, 0.88) !important;
  border-radius: 18px !important;
  box-shadow:
    0 4px 14px rgba(0, 0, 0, 0.06),
    inset 0 1px 1px rgba(255, 255, 255, 0.9) !important;
  padding: 4px !important;
}

ytd-menu-renderer yt-icon-button {
  border-radius: 14px !important;
}

ytd-menu-renderer yt-icon-button:hover {
  background: rgba(255, 255, 255, 0.82) !important;
}


/* ---------- POPUP MENUS ---------- */

ytd-popup-container {
  background: rgba(255, 255, 255, 0.94) !important;
  border: 1px solid rgba(255, 255, 255, 0.98) !important;
  border-radius: 20px !important;
  box-shadow:
    0 14px 38px rgba(0, 0, 0, 0.14),
    inset 0 1px 2px rgba(255, 255, 255, 1) !important;
  overflow: hidden !important;
}

ytd-menu-popup-renderer {
  background: rgba(255, 255, 255, 0.94) !important;
  border-radius: 18px !important;
}

ytd-menu-service-item-renderer {
  border-radius: 12px !important;
  margin: 3px 6px !important;
}

ytd-menu-service-item-renderer:hover {
  background: rgba(240, 242, 246, 0.9) !important;
}


/* ---------- WATCH PAGE ---------- */

ytd-watch-flexy {
  background: transparent !important;
}

ytd-watch-metadata {
  background: rgba(255, 255, 255, 0.55) !important;
  border: 1px solid rgba(255, 255, 255, 0.9) !important;
  border-radius: 22px !important;
  box-shadow:
    0 7px 22px rgba(0, 0, 0, 0.08),
    inset 0 1px 2px rgba(255, 255, 255, 0.95) !important;
  padding: 16px !important;
}

ytd-comments {
  background: rgba(255, 255, 255, 0.52) !important;
  border: 1px solid rgba(255, 255, 255, 0.88) !important;
  border-radius: 22px !important;
  box-shadow:
    0 7px 22px rgba(0, 0, 0, 0.07),
    inset 0 1px 2px rgba(255, 255, 255, 0.95) !important;
  padding: 16px !important;
}


/* ---------- VIDEO PLAYER ---------- */

ytd-video-primary-info-renderer {
  background: rgba(255, 255, 255, 0.58) !important;
  border-radius: 18px !important;
}

ytd-video-secondary-info-renderer {
  background: rgba(255, 255, 255, 0.58) !important;
  border-radius: 18px !important;
  margin-top: 10px !important;
}


/* ---------- WATCH PAGE ACTION AREA ---------- */

ytd-toggle-button-renderer {
  border-radius: 16px !important;
}

ytd-toggle-button-renderer:hover {
  background: rgba(255, 255, 255, 0.86) !important;
}

ytd-button-renderer:hover {
  background: rgba(255, 255, 255, 0.86) !important;
}


/* ---------- EXTRA GLASS DEFINITION ---------- */

ytd-rich-item-renderer,
ytd-watch-metadata,
ytd-comments,
ytd-video-primary-info-renderer,
ytd-video-secondary-info-renderer {
  backdrop-filter: none !important;
}


/* ---------- SMOOTH TRANSITIONS ---------- */

ytd-rich-item-renderer,
ytd-guide-entry-renderer,
yt-chip-cloud-chip-renderer,
ytd-button-renderer,
ytd-toggle-button-renderer,
ytd-searchbox {
  transition:
    background 0.2s ease,
    box-shadow 0.2s ease,
    transform 0.2s ease !important;
}
ytd-thumbnail {
  border-radius: 22px !important;
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.95),
    0 4px 12px rgba(0, 0, 0, 0.10),
    0 0 28px rgba(255, 255, 255, 0.85) !important;
  overflow: hidden !important;
  background: rgba(255, 255, 255, 0.35) !important;
}
